svg.metadata:
flowchart TB
  A["load / reload: read YAML"]
  B["Expand placeholders; apply hierarchical environment overrides"]
  C["Validate with the supplied schema"]
  D["Save the new value; reload notifies subscribers"]
  X["Return failure; retain the previous successful value"]
  A --> B
  B --> C
  C --> D
  A -->|"read fails"| X
  C -->|"validation fails"| X
  classDef default fill:#edf3ff,stroke:#476aab,color:#172b4d,stroke-width:1.5px;
  classDef good fill:#e9f6ef,stroke:#28734e,color:#17452f,stroke-width:1.5px;
  classDef stop fill:#fff0f0,stroke:#af4040,color:#742b2b,stroke-width:1.5px;
  classDef pending fill:#fff6df,stroke:#a07827,color:#654b18,stroke-width:1.5px;
  class D good;
  class X stop;
